public partial class Effects:MonoBehaviour {
 public BatGame game; StageView V=>game.view; int voices; GameObject activeDemo; Coroutine demoRoutine;
 public void ResetEffects(){if(V.spectacle)V.spectacle.ResetPulse();bulletPointSum=0;bulletPointRunning=false;CancelDemonstration();StopAllCoroutines();voicePitches.Clear();voices=0;if(V.fieldFence)V.fieldFence.SetColor("_BaseColor",BatGeometry.ColorOf("#426960"));}
 public void RecoveryHint(Vector3 p){game.bandHintUntil=game.now+.24;}
 IEnumerator RecoveryHintRoutine(Vector3 p){var original=V.band.GetColor("_BaseColor");StartCoroutine(Shockwave(p,"#FFE396",.65f));for(int i=0;i<2;i++){V.band.SetColor("_BaseColor",BatGeometry.ColorOf("#FFF8D8"));yield return EffectWait(.10f);V.band.SetColor("_BaseColor",original);yield return EffectWait(.10f);}V.band.SetColor("_BaseColor",original);}
 public void Sound(string name,float gain,float pitch,Vector3? origin=null){var clip=V.sounds.FirstOrDefault(x=>x&&x.name==name);if(!clip||voices>=14)return;var o=new GameObject("Sound "+name);o.transform.position=origin??(game.current!=null?game.W(game.current.position):Vector3.zero);o.transform.SetParent(game.targets,true);var a=o.AddComponent<AudioSource>();a.clip=clip;a.volume=Mathf.Pow(10,gain/20);a.pitch=pitch*game.SoundTimeScale;voicePitches[a]=pitch;a.spatialBlend=name=="select_001"||name=="click_001"?0:1;a.minDistance=.5f;a.maxDistance=origin.HasValue?90:6;a.rolloffMode=AudioRolloffMode.Custom;a.SetCustomCurve(AudioSourceCurveType.CustomRolloff,new AnimationCurve(new Keyframe(0,1),new Keyframe(1,.25f)));a.Play();voices++;StartCoroutine(EndVoice(o,a));}
 IEnumerator EndVoice(GameObject o,AudioSource a){yield return null;while(a&&(a.isPlaying||game.paused))yield return null;voicePitches.Remove(a);if(o)Destroy(o);voices=Mathf.Max(0,voices-1);}
 int bulletPointSum;bool bulletPointRunning;double bulletPointAt;Vector3 bulletPointPosition;
 public void Points(Vector3 p,int n){
  if(game.current?.kind!="bullets"){StartCoroutine(PointRoutine(p,n));return;}
  bulletPointSum+=n;bulletPointPosition=p;bulletPointAt=game.effectTime;
  if(!bulletPointRunning){bulletPointRunning=true;StartCoroutine(VolleyPoints());}
 }
 IEnumerator VolleyPoints(){while(game.effectTime-bulletPointAt<.20)yield return null;int points=bulletPointSum;bulletPointSum=0;bulletPointRunning=false;yield return PointRoutine(bulletPointPosition,points);}

 public void LaunchCue(Vector3 p){Burst(p,"smoke_01",6,.07f,.9f,.34f,BatGeometry.ColorOf("#7ADAE9"));StartCoroutine(Shockwave(p,"#55E5F5",.75f));}
 public void SlowCue(Vector3 p){Burst(p,"star_01",5,.024f,.55f,.24f,BatGeometry.ColorOf("#9BE6FF"));}
 public void Finale(){for(int i=0;i<5;i++)StartCoroutine(FinaleBurst(i));}
 IEnumerator FinaleBurst(int i){yield return EffectWait(i*.19f);var p=game.W(new Vector3((i-2)*1.2f,2.8f+((i%2)*.65f),5.3f+i*.48f));var tint=i%2==0?"#FFD179":"#65EAFF";StartCoroutine(Shockwave(p,tint,2.6f));StartCoroutine(ImpactFlash(p,tint));Burst(p,"star_01",32,.07f,3.0f,.78f,BatGeometry.ColorOf(tint));Sound("impactPunch_heavy_000",-16,.8f+i*.08f);}
 IEnumerator FieldPulse(Color tint){var mat=V.fieldFence;if(!mat)yield break;var original=mat.GetColor("_BaseColor");double start=game.effectTime;while(game.effectTime-start<.48){float t=(float)((game.effectTime-start)/.48);mat.SetColor("_BaseColor",Color.Lerp(tint*5,original,t));yield return null;}mat.SetColor("_BaseColor",original);}
 IEnumerator PointRoutine(Vector3 p,int n){var root=new GameObject("Award",typeof(RectTransform),typeof(UnityEngine.Canvas));root.transform.SetParent(game.targets,false);root.transform.position=p+new Vector3(-.22f*game.Mirror,.27f,-.04f);root.transform.localScale=Vector3.one*.001f;var panel=root.GetComponent<RectTransform>();panel.sizeDelta=new Vector2(170,72);root.GetComponent<UnityEngine.Canvas>().renderMode=RenderMode.WorldSpace;var text=V.Label(panel,(n>=0?"+":"")+n,Vector2.zero,new Vector2(.17f,.072f),.053f);double start=game.effectTime;while(game.effectTime-start<.52){float t=(float)(game.effectTime-start);panel.position=p+new Vector3((-.22f-.045f*Mathf.Clamp01(t/.52f))*game.Mirror,.27f+t/.52f*.09f,-.04f);text.color=n>=0?new Color(1,.88f,.43f,Mathf.Clamp01((.52f-t)/.18f)):new Color(1,.3f,.25f,Mathf.Clamp01((.52f-t)/.18f));yield return null;}Destroy(panel.gameObject);}
 public void Hit(string kind,Vector3 p,bool sweet){
  game.impactView.Pulse(kind);
  string sound=kind=="ball"?"impactMetal_light_000":kind=="cake"?"impactSoft_heavy_000":kind=="poison"?"impactPlate_light_000":kind=="boomerang"?"impactWood_medium_000":kind=="magic"?"impactBell_heavy_000":kind=="chest"?"impactWood_heavy_000":"impactMetal_medium_000";
  Sound(sound,sweet?-7:-10,kind=="bullets"?1.35f:kind=="magic"?1.2f:1,p);Haptic(sweet);
  if(sweet)Sound("impactPunch_heavy_000",-15,.65f,p);
  StartCoroutine(ContactAccent(p,kind,sweet));SpectacleContact(p,kind,sweet);
 }
 IEnumerator ImpactVectors(Vector3 p,string tint){var material=V.Glow(tint,1.5f);var lines=new LineRenderer[3];for(int i=0;i<3;i++)lines[i]=BatGeometry.Line("Contact direction",new[]{p,p},i==1?.018f:.010f,material,game.targets);double start=game.effectTime;while(game.effectTime-start<.22){float t=(float)((game.effectTime-start)/.22);for(int i=0;i<3;i++){float side=i-1;Vector3 direction=new Vector3(side*.20f,.14f+Mathf.Abs(side)*.04f,.54f);lines[i].SetPosition(0,p+direction*(t*.42f));lines[i].SetPosition(1,p+direction*(t*.42f+.35f));lines[i].widthMultiplier=(i==1?.018f:.010f)*(1-t);}yield return null;}foreach(var line in lines)Destroy(line.gameObject);Destroy(material);}
 IEnumerator Shockwave(Vector3 p,string tint,float radius){var material=V.Glow(tint,1.6f);var rings=new GameObject[1];for(int i=0;i<rings.Length;i++)rings[i]=BatGeometry.Ring("Impact shockwave",p+Vector3.forward*(.02f*i),.5f,.025f-i*.006f,material,game.targets);double start=game.effectTime;while(game.effectTime-start<.42){float t=(float)((game.effectTime-start)/.42);for(int i=0;i<rings.Length;i++){float phase=Mathf.Clamp01(t-i*.12f);rings[i].transform.localScale=Vector3.one*Mathf.Lerp(.08f,radius*(1+i*.22f)*.65f,phase);var line=rings[i].GetComponent<LineRenderer>();line.widthMultiplier=(.013f-i*.0025f)*(1-phase*.75f);line.startColor=new Color(1,1,1,1-phase);line.endColor=line.startColor;}yield return null;}foreach(var ring in rings)if(ring)Destroy(ring);Destroy(material);}
 IEnumerator ImpactFlash(Vector3 p,string tint){var o=new GameObject("Impact light burst");o.transform.SetParent(game.targets,false);o.transform.position=p;var light=o.AddComponent<Light>();light.type=LightType.Point;light.color=BatGeometry.ColorOf(tint);light.range=6;light.shadows=LightShadows.None;var coreMaterial=V.Glow(tint,1.2f);var spark=BatGeometry.Sphere("Impact core",p,Vector3.one*.075f,coreMaterial,game.targets);double start=game.effectTime;while(game.effectTime-start<.28){float t=(float)((game.effectTime-start)/.28);light.intensity=2.2f*(1-t);spark.transform.localScale=Vector3.one*(.025f+t*.025f);yield return null;}Destroy(spark);Destroy(o);Destroy(coreMaterial);}
 public void Haptic(bool sweet){var hand=InputDevices.GetDeviceAtXRNode(game.left?XRNode.LeftHand:XRNode.RightHand);if(hand.isValid&&hand.TryGetHapticCapabilities(out var caps)&&caps.supportsImpulse)hand.SendHapticImpulse(0,sweet?.8f:.55f,sweet?.16f:.10f);}
 public void Ring(Vector3 p,float startD,float endD,float duration,Material mat){StartCoroutine(RingRoutine(p,startD,endD,duration,mat));}
 IEnumerator RingRoutine(Vector3 p,float a,float b,float duration,Material mat){var o=BatGeometry.Ring("Impact ring",p,.5f,.015f,mat,game.targets);double start=game.effectTime;while(game.effectTime-start<duration){o.transform.localScale=Vector3.one*Mathf.Lerp(a,b,(float)(game.effectTime-start)/duration);yield return null;}Destroy(o);}
 public void Burst(Vector3 p,string tex,int count,float size,float speed,float life,Color color){for(int i=0;i<count;i++){float a=i*Mathf.PI*2/count;Vector3 d=new Vector3(Mathf.Cos(a)*.35f,.55f+Mathf.Sin(a)*.25f,1).normalized;StartCoroutine(Particle(p,d*speed,tex,size,life,color));}}
 IEnumerator Particle(Vector3 p,Vector3 v,string tex,float size,float life,Color color){var o=GameObject.CreatePrimitive(PrimitiveType.Quad);o.name="Particle "+tex;Destroy(o.GetComponent<Collider>());o.transform.SetParent(game.targets,false);var m=new Material(V.particleTemplate);m.SetFloat("_Surface",1);m.SetFloat("_Blend",0);m.SetFloat("_SrcBlend",5);m.SetFloat("_DstBlend",10);m.SetFloat("_ZWrite",0);m.SetFloat("_Cull",0);m.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");m.renderQueue=3000;m.SetTexture("_BaseMap",V.particles.FirstOrDefault(x=>x&&x.name==tex));m.SetColor("_BaseColor",color);o.GetComponent<Renderer>().sharedMaterial=m;o.transform.localScale=Vector3.one*size;float initialAlpha=color.a;double start=game.effectTime;while(game.effectTime-start<life){float t=(float)(game.effectTime-start);o.transform.position=p+v*t+Vector3.down*t*t;o.transform.rotation=game.view.eye.transform.rotation;color.a=initialAlpha*Mathf.Clamp01((life-t)/(life*.5f));m.SetColor("_BaseColor",color);yield return null;}Destroy(o);Destroy(m);}
 public void Return(GameObject o,Vector3 p,string kind,Vector3 offset){StartCoroutine(ReturnRoutine(o,p,kind,offset));}
 IEnumerator ReturnRoutine(GameObject o,Vector3 p,string kind,Vector3 offset){foreach(var trail in o.GetComponentsInChildren<TrailRenderer>()){trail.Clear();trail.enabled=false;}var streakMaterial=V.Glow(kind=="firework"?"#FFD68A":"#B6D4E7",kind=="firework"?1.6f:1.2f);var streak=BatGeometry.Line("Returned ball path",new[]{p,p},kind=="firework"?.014f:.009f,streakMaterial,game.targets);var streakPoints=new List<Vector3>{p};bool bullet=kind=="bullet"||kind=="bullets";Vector3 q=game.W(new Vector3(bullet?-.82f:.82f,1.7f,5.0f)+offset);Vector3 d=game.W(new Vector3(bullet?-.90f:.92f,kind=="firework"?1.8f:1.5f,(bullet?kind=="bullets"?5.405f:5.40f:kind=="firework"?5.10f:5.48f)+AFlight.FarTargetShift)+offset);double start=game.effectTime;
 while(o&&game.effectTime-start<.60){float t=(float)(game.effectTime-start)/.6f;Vector3 tangent=(d-p)*.5f;if(t<.5f)o.transform.position=Hermite(p,q,q-p,tangent,t*2);else o.transform.position=Hermite(q,d,tangent,d-q,(t-.5f)*2);streakPoints.Add(o.transform.position);if(streakPoints.Count>(kind=="firework"?18:4))streakPoints.RemoveAt(0);streak.positionCount=streakPoints.Count;streak.SetPositions(streakPoints.ToArray());yield return null;}if(o)o.transform.position=d;game.Event("far_contact",kind);if(kind=="firework"){game.Snap("firework-far",.50f);StartCoroutine(FireworkSky(d));StartCoroutine(FarNetPulse());StartCoroutine(ImpactFlash(d,"#70EFFF"));}else if(bullet){StartCoroutine(Shockwave(d,"#ACDFFF",1.8f));StartCoroutine(ImpactFlash(d,"#BDEAFF"));Sound("impactMetal_medium_000",-8,.8f);}else{StartCoroutine(Shockwave(d,"#FFC674",2.0f));StartCoroutine(ImpactFlash(d,"#FFE09B"));Sound("impactBell_heavy_000",-16,1.1f);}if(o){foreach(var renderer in o.GetComponentsInChildren<MeshRenderer>())renderer.enabled=false;Destroy(o,.55f);}StartCoroutine(FadeStreak(streak,streakMaterial,kind=="firework"?.36f:.18f));}
 IEnumerator FadeStreak(LineRenderer line,Material material,float duration){double start=game.effectTime;float original=line.widthMultiplier;while(line&&game.effectTime-start<duration){float t=(float)((game.effectTime-start)/duration);line.widthMultiplier=original*(1-t);yield return null;}if(line)Destroy(line.gameObject);Destroy(material);}
 IEnumerator FireworkSky(Vector3 hit){var sky=hit+new Vector3(game.Mirror*3.00f,1.00f,.08f);var material=V.Glow("#FFE8B6",1.5f);var line=BatGeometry.Line("Rising firework ember",new[]{hit,hit,hit},.010f,material,game.targets);double start=game.effectTime;while(game.effectTime-start<.22f){float t=(float)((game.effectTime-start)/.22f);float a=Mathf.Max(0,t-.28f);var from=Vector3.Lerp(hit,sky,a)+Vector3.up*(.12f*Mathf.Sin(Mathf.PI*a));var middle=Vector3.Lerp(hit,sky,(a+t)*.5f)+Vector3.up*(.12f*Mathf.Sin(Mathf.PI*(a+t)*.5f));var tip=Vector3.Lerp(hit,sky,t)+Vector3.up*(.12f*Mathf.Sin(Mathf.PI*t));line.SetPosition(0,from);line.SetPosition(1,middle);line.SetPosition(2,tip);yield return null;}Destroy(line.gameObject);Destroy(material);StartCoroutine(FireworkRays(sky));StartCoroutine(FireworkCore(sky));for(int i=0;i<24;i++){float a=i*2*Mathf.PI/24;StartCoroutine(Particle(sky,new Vector3(Mathf.Cos(a)*1.0f,.5f+Mathf.Sin(a)*1.0f,.1f),"star_01",.055f,.68f,new[]{V.gold.color,V.teal.color,BatGeometry.ColorOf("#D65357"),Color.white}[i%4]));}Sound("impactPunch_heavy_000",-6,.65f);}
 IEnumerator FireworkCore(Vector3 center){var material=V.Glow("#FFF1C2",2.6f);var core=BatGeometry.Sphere("Firework heart",center,Vector3.one*.08f,material,game.targets);var lamp=new GameObject("Firework light").AddComponent<Light>();lamp.transform.SetParent(game.targets,false);lamp.transform.position=center;lamp.type=LightType.Point;lamp.color=BatGeometry.ColorOf("#FFE2A5");lamp.range=3.2f;lamp.shadows=LightShadows.None;double start=game.effectTime;while(game.effectTime-start<.55){float t=(float)((game.effectTime-start)/.55);float envelope=t<.20f?Smooth(t/.20f):1-Smooth((t-.20f)/.35f);core.transform.localScale=Vector3.one*(.08f+.18f*envelope);material.SetColor("_BaseColor",BatGeometry.ColorOf("#FFF1C2")*(.5f+2.1f*envelope));lamp.intensity=4.0f*envelope;yield return null;}Destroy(core);Destroy(lamp.gameObject);Destroy(material);}
 IEnumerator FarNetPulse(){var mat=V.farNetMaterial;if(!mat)yield break;var original=mat.GetColor("_BaseColor");double start=game.effectTime;while(game.effectTime-start<.55){float t=(float)((game.effectTime-start)/.55);float strength=t<.12f?Smooth(t/.12f):1-Smooth((t-.12f)/.43f);mat.SetColor("_BaseColor",Color.Lerp(original,BatGeometry.ColorOf("#94F5F2")*3.0f,strength));yield return null;}mat.SetColor("_BaseColor",original);}
 IEnumerator FireworkRays(Vector3 center){var lines=new LineRenderer[24];var materials=new Material[24];for(int i=0;i<24;i++){string tint=new[]{"#FFD178","#74E5E2","#FF8D8C","#DAEDFF"}[i%4];materials[i]=V.Glow(tint,2.2f);lines[i]=BatGeometry.Line("Firework ray",new[]{center,center},i%3==0?.018f:.010f,materials[i],game.targets);}double start=game.effectTime;while(game.effectTime-start<.58){float t=(float)(game.effectTime-start);for(int i=0;i<24;i++){float angle=i*Mathf.PI/12;var direction=new Vector3(Mathf.Cos(angle),Mathf.Sin(angle),0);float phase=Mathf.Clamp01((t-(i%4)*.035f)/.37f);float radius=.88f*Smooth(phase);lines[i].SetPosition(0,center+direction*Mathf.Max(0,radius-.14f));lines[i].SetPosition(1,center+direction*radius);lines[i].widthMultiplier=(i%3==0?.018f:.010f)*(1-Mathf.Clamp01((t-.36f)/.22f));}yield return null;}for(int i=0;i<24;i++){Destroy(lines[i].gameObject);Destroy(materials[i]);}}
 Vector3 Hermite(Vector3 a,Vector3 b,Vector3 va,Vector3 vb,float t){return (2*t*t*t-3*t*t+1)*a+(t*t*t-2*t*t+t)*va+(-2*t*t*t+3*t*t)*b+(t*t*t-t*t)*vb;}
 public void Miss(GameObject o,Vector3 p,int lane){if(o)StartCoroutine(MissRoutine(o,p,lane));}
 IEnumerator MissRoutine(GameObject o,Vector3 p,int lane){float sign=lane>0?1:-1;var points=new[]{p,game.W(new Vector3(sign*.95f,.95f,.38f)),game.W(new Vector3(sign*1.05f,.95f,-.35f)),game.W(new Vector3(sign*.8f,.95f,-.78f))};var line=BatGeometry.Line("Recovery tube",points,.012f,V.teal,game.targets);double start=game.effectTime;while(o&&game.effectTime-start<.8){float t=(float)(game.effectTime-start)/.8f*3;int i=Mathf.Min(2,(int)t);o.transform.position=Vector3.Lerp(points[i],points[i+1],t-i);yield return null;}if(o)Destroy(o);Destroy(line.gameObject);}
 public void CakeBreak(GameObject o,Vector3 p){if(o)Destroy(o);Burst(p,"smoke_01",5,.026f,1.4f,.28f,new Color(.67f,.49f,.44f,.38f));for(int i=0;i<6;i++){float a=i*Mathf.PI/3;var vertices=new System.Collections.Generic.List<Vector3>{new Vector3(-.03f,0,-.03f),new Vector3(.03f,0,-.03f),new Vector3(0,0,.03f),new Vector3(-.03f,.05f,-.03f),new Vector3(.03f,.05f,-.03f),new Vector3(0,.05f,.03f)};var tri=new System.Collections.Generic.List<int>{0,2,1,3,4,5,0,1,3,1,4,3,1,2,4,2,5,4,2,0,5,0,3,5};var piece=BatGeometry.MeshObject("Cake fragment",vertices,tri,BatGeometry.Material(i%3==0?"#EA6E9A":i%3==1?"#BD865D":"#FFE2C5"),game.targets);var frostingVertices=new System.Collections.Generic.List<Vector3>{new Vector3(-.03f,.045f,-.03f),new Vector3(.03f,.045f,-.03f),new Vector3(0,.045f,.03f),new Vector3(-.03f,.058f,-.03f),new Vector3(.03f,.058f,-.03f),new Vector3(0,.058f,.03f)};var cream=V.Glow("#FBE4CC",.9f);BatGeometry.MeshObject("Cream layer",frostingVertices,tri,cream,piece.transform);Destroy(cream,.75f);StartCoroutine(Debris(piece,p,new Vector3(Mathf.Cos(a)*1.8f,1.4f+Mathf.Sin(a)*.45f,.7f),.65f));}for(int i=0;i<2;i++){var berry=V.Model(V.strawberry,"Strawberry",p,Vector3.one*.06f,false,game.targets);StartCoroutine(Debris(berry,p,new Vector3(i==0?-.5f:.5f,1.2f,1.6f),.65f));}}
