 public void ChestOpen(GameObject o,Vector3 p,bool large){StartCoroutine(OpenRoutine(o,p,large));}
 IEnumerator OpenRoutine(GameObject o,Vector3 p,bool large){var anim=o.GetComponentInChildren<Animation>();if(anim){foreach(AnimationState s in anim)if(s.name.Contains("open")&&!s.name.Contains("close")){s.speed=s.length/(large?.35f:.3f);s.wrapMode=WrapMode.ClampForever;anim.Play(s.name);break;}}else {var lid=o.GetComponentsInChildren<Transform>().FirstOrDefault(t=>t.name=="lid");if(lid)lid.localRotation*=Quaternion.Euler(-100,0,0);}
 int n=large?24:12;for(int i=0;i<n;i++){float a=2*Mathf.PI*i/n;var coin=BatGeometry.Lathe("Gold coin",new[]{-.003f,-.003f,.003f,.003f},new[]{0f,.0225f,.0225f,0f},V.gold,game.targets,12);StartCoroutine(Debris(coin,p+Vector3.up*.12f,new Vector3(Mathf.Cos(a)*.45f,1.1f+(i%3)*.22f,1.4f+(i%4)*.17f),large?1:.75f));}for(int i=0;i<(large?6:3);i++){var gem=BatGeometry.Gem("Reward gem",new Vector3(.065f,.09f,.065f),V.teal,game.targets);float a=i*2*Mathf.PI/(large?6:3);StartCoroutine(Debris(gem,p+Vector3.up*.12f,new Vector3(Mathf.Cos(a)*.6f,1.4f,1.55f),large?1:.75f));}if(true){var hero=BatGeometry.Gem("Hero gem",new Vector3(.12f,.18f,.12f),BatGeometry.Material("#7DDCFF",true),game.targets);hero.transform.position=p+new Vector3(0,.32f,.25f);Destroy(hero,1.1f);}
 Burst(p+Vector3.up*.12f,"star_01",large?22:18,.055f,2.4f,large?1:.75f,V.gold.color);Sound("confirmation_001",-14,1);double start=game.effectTime;while(o&&game.effectTime-start<1.1f){o.transform.position=p+Vector3.forward*Mathf.Min(.5f,(float)(game.effectTime-start));yield return null;}if(o)Destroy(o);}
