 IEnumerator DeliverRoutine(GameObject o,Vector3 p){V.Receiver(1);Sound("confirmation_001",-14,1);Burst(p,"star_01",6,.035f,.5f,.4f,V.gold.color);double start=game.effectTime;var q=p+Vector3.forward*.5f;var d=new Vector3(p.x,1.02f+game.dy,1.55f);while(o&&game.effectTime-start<.65f){float t=(float)(game.effectTime-start);o.transform.position=t<.35f?Vector3.Lerp(p,q,t/.35f):Vector3.Lerp(q,d,(t-.35f)/.3f);yield return null;}if(o)Destroy(o);V.Receiver(0);V.dockHinge.localRotation=Quaternion.identity;}
