 public void Demonstrate(string kind){CancelDemonstration();demoRoutine=StartCoroutine(Demonstration(kind));}
 public void CancelDemonstration(){if(demoRoutine!=null)StopCoroutine(demoRoutine);demoRoutine=null;if(activeDemo)Destroy(activeDemo);activeDemo=null;}
 IEnumerator Demonstration(string kind){var display=new GameObject("Background demonstration");activeDemo=display;display.transform.SetParent(game.targets,false);BatGeometry.Box("Robot demonstration stage",game.W(new Vector3(1.75f,.78f,2.40f)),new Vector3(1.4f,.12f,.85f),V.metal,display.transform);if(V.robot)V.Model(V.robot,"Demonstration robot",game.W(new Vector3(2.20f,.84f,2.62f)),new Vector3(.60f,.90f,.55f),true,display.transform);var demoLight=new GameObject("Demonstration spotlight").AddComponent<Light>();demoLight.transform.SetParent(display.transform,false);demoLight.transform.position=game.W(new Vector3(1.86f,2.04f,1.96f));demoLight.type=LightType.Point;demoLight.color=BatGeometry.ColorOf("#FFE4B4");demoLight.intensity=2.4f;demoLight.range=2.8f;demoLight.shadows=LightShadows.None;var focus=BatGeometry.Ring("Demonstration contact marker",game.W(new Vector3(1.62f,1.18f,2.10f)),.16f,.012f,V.gold,display.transform);var root=new GameObject("Demonstration sample rig");root.transform.SetParent(display.transform,false);root.transform.position=game.W(new Vector3(1.62f,1.18f,2.10f));root.transform.localScale=Vector3.one*.65f;var bat=BatGeometry.Bat(V.white,V.metal,V.band);bat.transform.SetParent(root.transform,false);var target=V.Target(kind,false,new Vector3(0,0,.53846f),root.transform);foreach(var renderer in display.GetComponentsInChildren<Renderer>())renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;double start=game.effectTime;bool cue=false;while(display&&game.effectTime-start<2.5f){float t=(float)(game.effectTime-start);focus.transform.localScale=Vector3.one*(.9f+.1f*Mathf.Sin(t*7));bat.transform.localRotation=Quaternion.FromToRotation(Vector3.up,Vector3.left);target.transform.localPosition=new Vector3(0,0,.53846f*(1-Smooth(t/1.2f)));bat.transform.localPosition=new Vector3(.43077f,0,.30769f*(1-Smooth((t-.5f)/.45f)));if(!cue&&t>=1.2f){cue=true;Burst(game.W(new Vector3(1.62f,1.18f,2.10f)),"spark_01",5,.018f,.65f,.25f,V.gold.color);}yield return null;}if(display)Destroy(display);activeDemo=null;demoRoutine=null;}
 static float Smooth(float t){t=Mathf.Clamp01(t);return t*t*t*(t*(t*6-15)+10);}
 public void BombFailure(Vector3 p){StartCoroutine(CoverRoutine());}
 IEnumerator CoverRoutine(){var cover=BatGeometry.Box("Safety cover",game.W(new Vector3(0,1.23f,.72f)),new Vector3(1.6f,.025f,.8f),V.table,game.targets);Sound("impactPunch_heavy_000",-6,.65f);Burst(game.W(new Vector3(0,1.15f,1.15f)),"smoke_01",8,.08f,.6f,.6f,Color.gray);double start=game.effectTime;while(game.effectTime-start<1){float t=(float)(game.effectTime-start);cover.transform.localScale=new Vector3(1.6f,.025f,.8f*Mathf.Clamp01(t/.2f));yield return null;}Destroy(cover);}
}
